/// <summary>
/// This class make updatePriceDiscMode default to keepManualsystem
/// </summary>
[ExtensionOf(classStr(SalesTable2LineUpdate))]
internal final class METSalesTable2LineUpdate_Extension
{
}

Method.Source:
/// <summary>
/// This method set the <c>updatePriceDiscMode</c> value to KeepManualSystem
/// This value will keep the salesLine values
/// </summary>
/// <param name = "_salesLine">SalesLine table buffer</param>
/// <param name = "_axSalesLine">The AxBC-class for the <c>SalesLine</c> record</param>
/// <param name = "_updateTaxGroup"> whether update the <c>TaxGroup</c> field or not.</param>
protected void modifySalesLine(SalesLine _salesLine, AxSalesLine  _axSalesLine, boolean _updateTaxGroup)
{
    if(GUPParameters::find().METSuppressPriceUpdate)
    {
        updatePriceDiscMode = PriceDiscUpdatePriceDisc::KeepManualSystem;
    }

    next modifySalesLine(_salesLine, _axSalesLine, _updateTaxGroup);
}
